from functools import lru_cache


def _components(grid):
    h, w = len(grid), len(grid[0])
    seen = [[False] * w for _ in range(h)]
    result = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or seen[r][c]:
                continue
            q = deque([(r, c)])
            seen[r][c] = True
            cells = set()
            while q:
                y, x = q.popleft()
                cells.add((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and not seen[ny][nx] and grid[ny][nx] == color:
                        seen[ny][nx] = True
                        q.append((ny, nx))
            top = min(y for y, _ in cells)
            left = min(x for _, x in cells)
            mask = frozenset((y - top, x - left) for y, x in cells)
            result.append((color, cells, mask))
    return result


def _placements(cells, mask):
    """Find a smallest collection of translated masks whose union is cells."""
    cells = frozenset(cells)
    max_r = max(r for r, _ in cells)
    max_c = max(c for _, c in cells)
    mh = max(r for r, _ in mask) + 1
    mw = max(c for _, c in mask) + 1
    candidates = []
    for top in range(max_r - mh + 2):
        for left in range(max_c - mw + 2):
            placed = frozenset((top + r, left + c) for r, c in mask)
            if placed <= cells:
                candidates.append((top, left, placed))
    by_cell = {}
    for i, (_, _, placed) in enumerate(candidates):
        for cell in placed:
            by_cell.setdefault(cell, []).append(i)

    @lru_cache(None)
    def cover(remaining):
        if not remaining:
            return ()
        cell = min(remaining)
        best = None
        for i in by_cell.get(cell, ()):
            placement = candidates[i]
            new_remaining = remaining - placement[2]
            if new_remaining == remaining:
                continue
            tail = cover(new_remaining)
            if tail is not None:
                proposal = (i,) + tail
                if best is None or len(proposal) < len(best):
                    best = proposal
        return best

    indices = cover(cells)
    if indices is None:
        return None
    return [(candidates[i][0], candidates[i][1]) for i in indices]


def transform(grid):
    h, w = len(grid), len(grid[0])
    components = _components(grid)
    if not components:
        return [row[:] for row in grid]

    # The repeated shape is the most common normalized component silhouette.
    counts = Counter(mask for _, _, mask in components)
    template = max(counts, key=lambda m: (counts[m], len(m)))

    # The color-8 object is the alignment reference in all demonstrated cases.
    anchor = min(r for r in range(h) for c in range(w) if grid[r][c] == 8)
    out = [[0] * w for _ in range(h)]
    for color, cells, mask in components:
        if mask == template:
            instances = [(min(r for r, _ in cells), min(c for _, c in cells))]
        else:
            instances = _placements(cells, template)
            if instances is None:
                instances = [(min(r for r, _ in cells), min(c for _, c in cells))]
        for _top, left in instances:
            for dr, dc in template:
                rr, cc = anchor + dr, left + dc
                if 0 <= rr < h and 0 <= cc < w:
                    out[rr][cc] = color
    return out


if __name__ == '__main__':
    print('task-638cc6c0 transform ready')
