from functools import lru_cache


def _placements(cells, mask):
    cells = frozenset(cells)
    max_r = max(r for r, _ in cells)
    max_c = max(c for _, c in cells)
    mh = max(r for r, _ in mask) + 1
    mw = max(c for _, c in mask) + 1
    options = []
    by_cell = {}
    for top in range(max_r - mh + 2):
        for left in range(max_c - mw + 2):
            placed = frozenset((top + dr, left + dc) for dr, dc in mask)
            if placed <= cells:
                i = len(options)
                options.append((top, left, placed))
                for cell in placed:
                    by_cell.setdefault(cell, []).append(i)

    @lru_cache(None)
    def cover(rem):
        if not rem:
            return ()
        cell = min(rem)
        best = None
        for i in by_cell.get(cell, ()):
            remaining = rem - options[i][2]
            if remaining == rem:
                continue
            tail = cover(remaining)
            if tail is not None and (best is None or len(tail) + 1 < len(best)):
                best = (i,) + tail
        return best

    result = cover(cells)
    if result is None:
        return None
    return [(options[i][0], options[i][1]) for i in result]


def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = [[False] * w for _ in range(h)]
    components = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or seen[r][c]:
                continue
            q = deque([(r, c)])
            seen[r][c] = True
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and not seen[ny][nx] and grid[ny][nx] == color:
                        seen[ny][nx] = True
                        q.append((ny, nx))
            top = min(y for y, _ in cells)
            left = min(x for _, x in cells)
            mask = frozenset((y - top, x - left) for y, x in cells)
            components.append((color, cells, mask))

    if not components:
